// Generated by tools/gen_shells.py. Bump VERSION there when any file changes.
const VERSION = 8;
const CACHE = 'fill-v' + VERSION;
const ASSETS = [
  "./",
  "./index.html",
  "./game.js",
  "./manifest.webmanifest",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "../shared/toddler.js"
];

// cache: 'reload' skips the browser's HTTP cache, so the offline copy is never a mix of old and new files.
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS.map(u => new Request(u, { cache: 'reload' })))));
  self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys =>
    Promise.all(keys.filter(k => k.startsWith('fill-') && k !== CACHE).map(k => caches.delete(k)))));
  self.clients.claim();
});

// Network first (revalidated, never a stale HTTP-cache copy), so updates show up on the next launch.
// The cache is only the offline fallback, and every fresh response refreshes it.
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(
    fetch(new Request(req, { cache: 'no-cache' }))
      .then(res => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          e.waitUntil(caches.open(CACHE).then(c => c.put(req.url, copy)));
        }
        return res;
      })
      .catch(() => caches.match(req, { ignoreSearch: true }).then(r => r || Response.error()))
  );
});
